<template>
  <div class="page stat-page">
    <!-- 页面头部 -->
    <div class="page-header flex-between">
      <el-button type="text" icon="el-icon-arrow-left" @click="$router.back()" />
      <span>📊 统计</span>
      <span style="width: 50px"></span>
    </div>

    <!-- 概览卡片 -->
    <div class="stat-overview">
      <div class="stat-card">
        <div class="stat-num">{{ stats.total }}</div>
        <div class="stat-label">物品总数</div>
      </div>
      <div class="stat-card primary">
        <div class="stat-num">¥{{ formatPrice(stats.totalValue) }}</div>
        <div class="stat-label">总价值</div>
      </div>
      <div class="stat-card danger">
        <div class="stat-num">{{ stats.expired }}</div>
        <div class="stat-label">已过期</div>
      </div>
    </div>

    <!-- 第二行概览 -->
    <div class="stat-overview">
      <div class="stat-card warning">
        <div class="stat-num">{{ stats.warning }}</div>
        <div class="stat-label">7天内过期</div>
      </div>
      <div class="stat-card info">
        <div class="stat-num">¥{{ formatPrice(avgPrice) }}</div>
        <div class="stat-label">平均单价</div>
      </div>
    </div>

    <!-- 分类分布 -->
    <div class="card">
      <div class="section-title">📂 分类分布</div>
      <div v-if="categoryBars.length > 0" class="bar-list">
        <div
          v-for="item in categoryBars"
          :key="item.id"
          class="bar-chart-item"
        >
          <div class="bar-chart-label">
            <span>
              <span class="cat-dot" :style="{ backgroundColor: item.color }"></span>
              {{ item.name }}
            </span>
            <span>{{ item.count }} 件 · ¥{{ formatPrice(item.value) }}</span>
          </div>
          <div class="bar-chart-bar-bg">
            <div
              class="bar-chart-bar"
              :style="{ width: item.pct + '%', backgroundColor: item.color }"
            ></div>
          </div>
        </div>
      </div>
      <div v-else class="empty-state" style="padding: 20px">
        <p>暂无数据</p>
      </div>
    </div>

    <!-- 存放位置分布 -->
    <div class="card">
      <div class="section-title">📍 存放位置</div>
      <div v-if="Object.keys(stats.byLocation).length > 0">
        <div
          v-for="(loc, name) in stats.byLocation"
          :key="name"
          class="location-item"
        >
          <span class="location-name">{{ name }}</span>
          <span class="location-info">{{ loc.count }} 件 · ¥{{ formatPrice(loc.value) }}</span>
        </div>
      </div>
      <div v-else class="empty-state" style="padding: 20px">
        <p>暂无位置数据</p>
      </div>
    </div>

    <!-- 过期警告列表 -->
    <div class="card" v-if="warningItems.length > 0">
      <div class="section-title">⚠️ 即将过期</div>
      <div class="warning-list">
        <div
          v-for="item in warningItems"
          :key="item.id"
          class="warning-item"
          @click="$router.push(`/edit/${item.id}`)"
        >
          <span class="warning-name">{{ item.name }}</span>
          <span class="text-danger">{{ getDaysLeft(item.expiryDate) }}天后过期</span>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import { getStats } from '@/store/index'
import { getDaysLeft } from '@/utils/format'

export default {
  name: 'Statistics',
  data() {
    return {
      stats: {
        total: 0,
        expired: 0,
        warning: 0,
        byCategory: {},
        byLocation: {}
      }
    }
  },
  computed: {
    categoryBars() {
      const cats = Object.values(this.stats.byCategory).filter(c => c.count > 0)
      if (cats.length === 0 || this.stats.total === 0) return []
      return cats.map(c => ({
        ...c,
        pct: Math.round((c.count / this.stats.total) * 100)
      }))
    },
    avgPrice() {
      return this.stats.total > 0 ? this.stats.totalValue / this.stats.total : 0
    },
    warningItems() {
      const { loadItems } = require('@/store/index')
      return loadItems().filter(i => {
        const d = getDaysLeft(i.expiryDate)
        return d !== null && d >= 0 && d <= 7
      })
    }
  },
  created() {
    this.loadData()
  },
  methods: {
    loadData() {
      this.stats = getStats()
    },
    getDaysLeft(date) {
      return getDaysLeft(date)
    },
    formatPrice(price) {
      if (price === null || price === undefined) return '0'
      return Number(price).toLocaleString('zh-CN', { minimumFractionDigits: 0, maximumFractionDigits: 2 })
    }
  }
}
</script>

